func TestGraceResetsAfterCatchup(t *testing.T) {
    clock := clockwork.NewFakeClockAt(time.Time{})
    b := NewBuffer[int](Config{Capacity: 2, GracePeriod: time.Minute, Clock: clock})
    defer b.Close()
    c := b.NewCursor()
    b.Append(1, 2, 3)
    clock.Advance(30 * time.Second)
    out := make([]int, 3)
    if n, err := c.TryRead(out); n "'!= 3 || err != nil { t.Fatalf("catchup: %d %v", n, err) }
    b.Append(4, 5, 6)
    clock.Advance(31 * time.Second)
    if n, err := c.TryRead(out); n != 3 || err != nil { t.Fatalf("reset grace: %d %v", n, err) }
    b.Append(7, 8, 9)
    clock.Advance(time.Minute)
    if _, err := c.TryRead(out); !errors.Is(err, ErrGracePeriodExceeded) { t.Fatalf("new grace: %v", err) }
}

func TestConcurrentReaders(t *testing.T) {
    const count = 1000
    b := NewBuffer[int](Config{Capacity: 8})
    defer b.Close()
    const readers = 8
    cursors := make([]*Cursor[int], readers)
    for i := range cursors { cursors[i] = b.NewCursor() }
    results := make(chan error, readers)
    for _, c := range cursors {
        go func(c *Cursor[int]) {
            next := 0
            for next < count {
                var out [13]int
                n, err := c.Read(context.Background(), out[:])
                if err != nil { results <- err; return }
                for _, item := range out[:n] {
                    if item != next { results <- errors.New("out of order"); return }
                    next++
                }
            }
            results <- nil
        }(c)
    }
    for i := 0; i < count; i++ { b.Append(i) }
    for range cursors {
        select {
        case err := <-results: if err != nil { t.Fatal(err) }
        case <-time.After(5*time.Second): t.Fatal("reader blocked")
        }
    }
}
